page.on('pageerror',e=>errors.push(String(e)));page.on('response',r=>{if(r.status()>=400)errors.push(r.status()+' '+r.url());if(new URL(r.url()).pathname.startsWith('/product/source/'))jobs.push((async()=>{let p=path.join(root,new URL(r.url()).pathname);if(fs.statSync(p).isDirectory())p=path.join(p,'index.html');const data=await r.body();responses.push({url:r.url(),sha256:crypto.createHash('sha256').update(data).digest('hex'),matches:data.equals(fs.readFileSync(p))});})().catch(e=>errors.push(String(e))));});page.on('dialog',d=>d.accept());
